const items={peroxide:{name:'豆干',formula:'H₂O₂',agent:'過氧化氫'},chlorine:{name:'衣服',formula:'NaClO',agent:'次氯酸鈉'},sulfur:{name:'竹筷',formula:'SO₂',agent:'二氧化硫'}};
export function bleachSupply(key){const d=items[key];return `<svg class="bleach-supply" viewBox="0 0 120 120" aria-hidden="true"><defs><linearGradient id="reagent-${key}"><stop stop-color="#546d69"/><stop offset=".28" stop-color="#bdd0c5"/><stop offset=".65" stop-color="#879f95"/><stop offset="1" stop-color="#405d5a"/></linearGradient></defs><ellipse cx="60" cy="108" rx="29" ry="5" fill="#203f3222"/><path d="M43 30V43L32 53V100Q60 111 88 100V53L77 43V30Z" fill="url(#reagent-${key})" stroke="#526d65"/><rect x="41" y="20" width="38" height="16" rx="3" fill="#365650"/><path d="M47 23v10m7-10v10m7-10v10m7-10v10m7-10v10" stroke="#829990"/><rect x="34" y="60" width="52" height="31" rx="3" fill="#fff8df"/><text x="60" y="79" text-anchor="middle" font-size="15" fill="#385650">${d.formula}</text></svg><strong>${d.agent} ${d.formula}</strong>`;}
function specimen(key,x,changed=false){const dye=changed?' class="life-dye-after"':'';
 if(key==='peroxide')return `<g transform="translate(${x} 156)"><ellipse cx="0" cy="101" rx="105" ry="27" fill="#54716933"/><ellipse cx="0" cy="85" rx="112" ry="34" fill="#dce4d9" stroke="#789089"/><ellipse cx="0" cy="82" rx="100" ry="26" fill="#f9f8e9" stroke="#a3b6a7"/><g><path d="M-66 4L48-5 77 23 72 84-36 95-69 64Z" fill="#d8c5a1" stroke="#ab9674"/><path d="M-66 4L-36 31 77 23 48-5Z" fill="#e9d7b5"/><g${dye} fill="#946038"><path d="M-66 4L48-5 77 23 72 84-36 95-69 64Z"/><path d="M-66 4L-36 31 77 23 48-5Z" fill="#b6844f"/></g><path d="M-36 31V95M-36 31L77 23M-66 4L-36 31" fill="none" stroke="#6b512e" opacity=".28"/>${Array.from({length:22},(_,i)=>`<circle cx="${-52+(i*31)%111}" cy="${35+(i*17)%43}" r="1.6" fill="#705631" opacity=".19"/>`).join('')}</g></g>`;
 if(key==='chlorine')return `<g transform="translate(${x} 116)"><ellipse cx="0" cy="156" rx="110" ry="18" fill="#2d494b22"/><path d="M-30 6Q0 25 30 6L83 29 104 75 67 94 51 66 55 153Q0 164-55 153L-51 66-67 94-104 75-83 29Z" fill="#f1eee1" stroke="#a7b3a7" stroke-width="2"/><path d="M-30 6Q0 40 30 6M-49 62L-46 145M49 62L46 145M-50 143Q0 151 50 143" fill="none" stroke="#c8cfc0" stroke-width="2"/><g${dye}><path d="M-16 57Q14 38 31 68T16 105Q-16 117-31 91T-16 57" fill="#a36b52" opacity=".8"/><path d="M-17 64Q7 55 17 77M-18 91L17 95" fill="none" stroke="#8f5644" stroke-width="5" opacity=".3"/></g></g>`;
 return `<g transform="translate(${x} 130)"><path d="M-113 127L77 144 114 98-79 82Z" fill="#b7c9c4" stroke="#6a8581"/><path d="M-113 127V135L77 154V144L114 98V108L77 154" fill="#7b9992"/><g transform="rotate(-13)">${[0,1,2,3,4,5].map(i=>`<g transform="translate(${-70+i*24} 0)"><path d="M-4 0H6L4 129H-2Z" fill="#e7d5a0" stroke="#b4a373"/><path d="M0 5V122" stroke="#f7ecc5"/><path d="M-4 0H6L4 129H-2Z" fill="#b48d4c"${dye}/><path d="M-2 29H5M-2 92H4" stroke="#8e783e" opacity=".3"/></g>`).join('')}</g><path d="M-122 147V-37Q0-55 122-37V147" fill="#eefbf7" fill-opacity=".12" stroke="#9cb8b1" stroke-width="2"/><path d="M-111-24V123" stroke="white" opacity=".6"/><rect x="-62" y="-48" width="124" height="17" rx="7" fill="#637f79"/><text x="0" y="-57" text-anchor="middle" font-size="12" fill="#536f69">密閉示意罩</text></g>`;
}
export function bleachLabArt(key){const d=items[key];return `<svg viewBox="0 0 660 340" role="img" aria-label="實驗室中${d.agent}作用於${d.name}的前後對照"><defs><linearGradient id="bleach-room-${key}" x2="0" y2="1"><stop stop-color="#f2f5ec"/><stop offset="1" stop-color="#d7e4dc"/></linearGradient><linearGradient id="bleach-table-${key}" x2="0" y2="1"><stop stop-color="#7c9890"/><stop offset=".18" stop-color="#a2b7ac"/><stop offset="1" stop-color="#536f69"/></linearGradient></defs><rect width="660" height="340" fill="url(#bleach-room-${key})"/><path d="M0 70H660M0 140H660M0 210H660M110 0V256M220 0V256M330 0V256M440 0V256M550 0V256" stroke="#b8cbc0" opacity=".4"/><rect y="253" width="660" height="87" fill="url(#bleach-table-${key})"/><path d="M0 253H660M20 317H640" stroke="#dce8df" opacity=".65"/><text x="330" y="28" text-anchor="middle" font-size="13" fill="#5b7569">實驗室觀察台 · ${d.name}</text>${specimen(key,164,false)}${specimen(key,495,true)}<g class="bleach-dose-animation">${key==='sulfur'?'<path d="M594 69Q552 61 508 84" fill="none" stroke="#78998d" stroke-width="2"/><path d="M519 72L507 84 523 84" fill="none" stroke="#78998d" stroke-width="2"/><text x="579" y="58" font-size="14" fill="#536f69">SO₂ 進入</text>':'<g transform="translate(449 57) rotate(32)"><path d="M0 0H30V18L38 25V67Q15 74-8 67V25L0 18Z" fill="#718c80" stroke="#425f54"/><rect x="-2" y="-5" width="34" height="13" rx="2" fill="#38594e"/><rect x="-5" y="35" width="40" height="22" rx="3" fill="#f4f0da"/><text x="15" y="51" text-anchor="middle" font-size="11" fill="#3e5f51">'+d.formula+'</text></g><path class="bleach-agent-trail" d="M495 113Q488 137 496 158" fill="none" stroke="#a2c9c6" stroke-width="3" stroke-dasharray="4 6"/>'}</g><text x="164" y="311" text-anchor="middle" fill="#f4f5e9" font-size="13">原樣對照</text><text x="495" y="311" text-anchor="middle" fill="#f4f5e9" font-size="13">加入${d.agent}後</text></svg>`;}
